struct Base {
    int id;               // Data member
    virtual void log() const = 0; // Requires v-ptr
    virtual ~Base() = default; // Polymorphic destruction
};

struct Derived : Base {
    long data;
    void log() const override {}
    // Derived object contains:
    // 1. V-pointer (layout dependent)
    // 2. Base subobject (id)
    // 3. Derived member (data)
};

void dynamic_call(Base* ptr) {
    ptr->log(); // Runtime dispatch via v-table
}

Base* heap_obj = new Derived(); // Dynamic storage duration
delete heap_obj;
// delete heap_obj requires virtual dtor for correct cleanup.
// Lifetime ends here.
